/**
 * Juez oculto de la medición del tema 02.
 *
 * El agente no lo ve durante la sesión. Se copia al repo cuando la sesión termina y
 * decide si la tarea quedó bien hecha. Mockea el SDK de Gemini, así que no usa red.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";

const generateContent = vi.fn();

vi.mock("@google/genai", () => ({
  GoogleGenAI: class {
    models = { generateContent };
  },
}));

const PLAN = {
  intro: "Tres días en Antigua",
  days: [
    { day: 1, title: "Centro", activities: ["Arco de Santa Catalina"] },
    { day: 2, title: "Volcanes", activities: ["Pacaya"] },
    { day: 3, title: "Café", activities: ["Finca en San Miguel Escobar"] },
  ],
  hiddenGem: { title: "Cerro de la Cruz", description: "Vista al Volcán de Agua" },
  localFood: { dish: "Pepián", description: "Recado de semillas tostadas" },
};

async function postWithModelText(text: string, body: unknown = { destination: "Antigua" }) {
  generateContent.mockResolvedValue({ text });
  const { POST } = await import("@/app/api/ai-plan/route");
  const res = await POST(
    new Request("http://localhost/api/ai-plan", { method: "POST", body: JSON.stringify(body) })
  );
  return { status: res.status, json: await res.json() };
}

describe("Juez · plan de viaje válido o 502", () => {
  beforeEach(() => {
    generateContent.mockReset();
    process.env.GOOGLE_GENAI_API_KEY = "test-key";
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "log").mockImplementation(() => {});
  });

  it("un plan completo llega con 200", async () => {
    const { status, json } = await postWithModelText(JSON.stringify(PLAN));
    expect(status).toBe(200);
    expect(json.plan.days).toHaveLength(3);
  });

  it("acepta el JSON envuelto en un bloque ```json", async () => {
    const { status, json } = await postWithModelText("```json\n" + JSON.stringify(PLAN) + "\n```");
    expect(status).toBe(200);
    expect(json.plan.localFood.dish).toBe("Pepián");
  });

  it("sin localFood responde 502 invalid_plan", async () => {
    const rest = { intro: PLAN.intro, days: PLAN.days, hiddenGem: PLAN.hiddenGem };
    const { status, json } = await postWithModelText(JSON.stringify(rest));
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });

  it("con dos días responde 502 invalid_plan", async () => {
    const { status, json } = await postWithModelText(JSON.stringify({ ...PLAN, days: PLAN.days.slice(0, 2) }));
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });

  it("un día sin actividades responde 502 invalid_plan", async () => {
    const days = PLAN.days.map((d, i) => (i === 1 ? { ...d, activities: [] } : d));
    const { status, json } = await postWithModelText(JSON.stringify({ ...PLAN, days }));
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });

  it("texto que no es JSON responde 502 invalid_plan", async () => {
    const { status, json } = await postWithModelText("Lo siento, no puedo ayudar con eso.");
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });

  it("sin destino sigue respondiendo 400", async () => {
    const { status } = await postWithModelText(JSON.stringify(PLAN), {});
    expect(status).toBe(400);
  });
});
import { NextResponse } from 'next/server';
import { GeminiService } from '@/services/gemini';

export async function POST(request: Request) {
    try {
        const body = await request.json();
        const { destination, context } = body;

        if (!destination) {
            return NextResponse.json({ error: 'Destination is required' }, { status: 400 });
        }

        const plan = await GeminiService.generateTravelPlan(destination, context);
        if (plan === null) {
            return NextResponse.json({ error: 'invalid_plan' }, { status: 502 });
        }
        return NextResponse.json({ plan });

    } catch (error) {
        console.error('API Plan Error:', error);
        return NextResponse.json({ error: 'Failed to generate plan' }, { status: 500 });
    }
}
import { GoogleGenAI } from "@google/genai";

export const PLAN_MODEL = "gemini-3.8-flash";

let client: GoogleGenAI | null = null;

function getClient(): GoogleGenAI {
    if (client === null) {
        client = new GoogleGenAI({ apiKey: process.env.GOOGLE_GENAI_API_KEY || "" });
    }
    return client;
}

export interface TravelPlan {
    intro: string;
    days: {
        day: number;
        title: string;
        activities: string[];
    }[];
    hiddenGem: {
        title: string;
        description: string;
    };
    localFood: {
        dish: string;
        description: string;
    };
}

function isNonEmptyString(value: unknown): value is string {
    return typeof value === "string" && value.trim().length > 0;
}

function isTravelPlan(value: unknown): value is TravelPlan {
    if (typeof value !== "object" || value === null) return false;
    const plan = value as Record<string, unknown>;
    if (!isNonEmptyString(plan.intro) || !Array.isArray(plan.days) || plan.days.length !== 3) return false;
    if (!plan.days.every((day) => {
        if (typeof day !== "object" || day === null) return false;
        const candidate = day as Record<string, unknown>;
        return typeof candidate.day === "number" && isNonEmptyString(candidate.title) &&
            Array.isArray(candidate.activities) && candidate.activities.length > 0 &&
            candidate.activities.every(isNonEmptyString);
    })) return false;
    if (typeof plan.hiddenGem !== "object" || plan.hiddenGem === null ||
        typeof plan.localFood !== "object" || plan.localFood === null) return false;
    const hiddenGem = plan.hiddenGem as Record<string, unknown>;
    const localFood = plan.localFood as Record<string, unknown>;
    return isNonEmptyString(hiddenGem.title) && isNonEmptyString(hiddenGem.description) &&
        isNonEmptyString(localFood.dish) && isNonEmptyString(localFood.description);
}

function cleanJsonBlock(text: string): string {
    const trimmed = text.trim();
    const block = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    return block ? block[1].trim() : trimmed;
}

export const GeminiService = {
    generateTravelPlan: async (destinationName: string, context?: string): Promise<TravelPlan | null> => {
        try {
            if (!process.env.GOOGLE_GENAI_API_KEY) {
                console.error("Gemini Service: Missing GOOGLE_GENAI_API_KEY");
                throw new Error("Missing Google API Key");
            }

            const prompt = `
        Act as an expert travel guide. Create a 3-day itinerary for ${destinationName} ${context ? `(${context})` : ''}.

        Requirements:
        - Tone: Enthusiastic, immersive, and practical.
        - Language: Spanish (Español).
        - Output Format: JSON ONLY. Do not use Markdown code blocks.

        JSON Schema:
        {
          "intro": "1 sentence hook",
          "days": [
            { "day": 1, "title": "Theme of the day (e.g. Historic Center)", "activities": ["Activity 1", "Activity 2", "Activity 3"] }
          ],
          "hiddenGem": { "title": "Name", "description": "Why it is special" },
          "localFood": { "dish": "Name", "description": "What is it" }
        }
      `;

            const response = await getClient().models.generateContent({
                model: PLAN_MODEL,
                contents: prompt,
                config: { responseMimeType: "application/json" },
            });
            const text = response.text ?? "";

            // console.log("Gemini JSON Response:", text); // Debug removed per user request

            const parsed: unknown = JSON.parse(cleanJsonBlock(text));
            return isTravelPlan(parsed) ? parsed : null;

        } catch (error) {
            console.error("Gemini AI Error:", error);
            return null;
        }
    }
};
import { z } from "zod";

export const ItineraryDaySchema = z.object({
  day: z.number().int().positive(),
  title: z.string().trim().min(1),
  activities: z.array(z.string().trim().min(1)).min(1),
});

export const ItineraryResponseSchema = z.object({
  intro: z.string().trim().min(1),
  days: z.array(ItineraryDaySchema).length(3),
  hiddenGem: z.object({
    title: z.string().trim().min(1),
    description: z.string().trim().min(1),
  }),
  localFood: z.object({
    dish: z.string().trim().min(1),
    description: z.string().trim().min(1),
  }),
});

export type TravelPlan = z.infer<typeof ItineraryResponseSchema>;
