/** Juez de la tarea `descarga`: funciones públicas de src/lib/itinerary-markdown.ts. Sin red. */
import { describe, it, expect, vi, afterEach } from "vitest";

const plan = {
  intro: "Intro",
  days: [
    { day: 1, title: "Centro", activities: ["Arco", "Catedral"], costUsd: 30 },
    { day: 2, title: "Volcanes", activities: ["Pacaya"], costUsd: 50 },
  ],
  hiddenGem: { title: "Cerro", description: "Vista" },
  localFood: { dish: "Pepián", description: "Recado" },
  totalUsd: 80,
};

afterEach(() => vi.unstubAllGlobals());

describe("Juez · descargar itinerario", () => {
  it("el nombre de archivo no lleva espacios ni acentos", async () => {
    const { itineraryFilename } = await import("@/lib/itinerary-markdown");
    expect(itineraryFilename("Antigua Guatemala")).toBe("antigua-guatemala.md");
    expect(itineraryFilename("Quetzaltenango Ciudad Éxito")).toBe("quetzaltenango-ciudad-exito.md");
    expect(itineraryFilename("  Panajachel  ")).toBe("panajachel.md");
  });

  it("el markdown trae destino como título, un encabezado por día y actividades en lista", async () => {
    const { itineraryToMarkdown } = await import("@/lib/itinerary-markdown");
    const md = itineraryToMarkdown("Antigua Guatemala", plan);
    const lines = md.split("\n");
    expect(lines[0]).toBe("# Antigua Guatemala");
    expect(lines.filter((l) => /^## /.test(l) && /Día [12]/.test(l))).toHaveLength(2);
    expect(md).toMatch(/^- Arco$/m);
    expect(md).toMatch(/^- Catedral$/m);
    expect(md).toMatch(/^- Pacaya$/m);
  });

  it("downloadItinerary entrega un Blob markdown con el nombre correcto", async () => {
    const click = vi.fn();
    const anchor: { href: string; download: string; click: () => void } = { href: "", download: "", click };
    const createObjectURL = vi.fn(() => "blob:fake");
    vi.stubGlobal("document", {
      createElement: vi.fn(() => anchor),
      body: { appendChild: vi.fn(), removeChild: vi.fn() },
    });
    vi.stubGlobal("URL", Object.assign(URL, { createObjectURL, revokeObjectURL: vi.fn() }));
    const { downloadItinerary } = await import("@/lib/itinerary-markdown");
    downloadItinerary("Antigua Guatemala", plan);
    expect(click).toHaveBeenCalledOnce();
    expect(anchor.download).toBe("antigua-guatemala.md");
    const blob = (createObjectURL.mock.calls as unknown as [Blob][])[0][0];
    expect(blob.type).toContain("markdown");
  });
});
EOF
cat > api.juez.test.ts <<'EOF'
/** Juez de la tarea `api`: POST /api/ai-plan con duración y presupuesto. Mockea @google/genai, sin red. */
import { describe, it, expect, vi, beforeEach } from "vitest";

const generateContent = vi.fn();

vi.mock("@google/genai", () => ({
  GoogleGenAI: class {
    models = { generateContent };
  },
}));

function planWith(n: number, extra: Record<string, unknown> = {}, cost: unknown = 20) {
  return {
    intro: "Intro",
    days: Array.from({ length: n }, (_, i) => ({
      day: i + 1,
      title: `Día ${i + 1}`,
      activities: ["Algo"],
      costUsd: cost,
    })),
    hiddenGem: { title: "g", description: "d" },
    localFood: { dish: "p", description: "d" },
    ...extra,
  };
}

async function post(modelPlan: unknown, body: unknown = { destination: "Antigua" }) {
  generateContent.mockResolvedValue({ text: JSON.stringify(modelPlan) });
  const { POST } = await import("@/app/api/ai-plan/route");
  const res = await POST(
    new Request("http://localhost/api/ai-plan", { method: "POST", body: JSON.stringify(body) })
  );
  return { status: res.status, json: await res.json() };
}

describe("Juez · duración y presupuesto en el API", () => {
  beforeEach(() => {
    generateContent.mockReset();
    process.env.GOOGLE_GENAI_API_KEY = "test-key";
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "log").mockImplementation(() => {});
  });

  it("sin days sigue siendo un plan de 3 días", async () => {
    const { status, json } = await post(planWith(3));
    expect(status).toBe(200);
    expect(json.plan.days).toHaveLength(3);
  });

  it.each([2, 5, 7])("days=%i devuelve exactamente ese número de días", async (n) => {
    const { status, json } = await post(planWith(n), { destination: "Antigua", days: n });
    expect(status).toBe(200);
    expect(json.plan.days).toHaveLength(n);
  });

  it("si el modelo trae otro número de días responde 502 invalid_plan", async () => {
    const { status, json } = await post(planWith(4), { destination: "Antigua", days: 5 });
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });

  it("el prompt al modelo pide el número de días elegido", async () => {
    await post(planWith(6), { destination: "Antigua", days: 6 });
    const prompt = JSON.stringify(generateContent.mock.calls[0][0]);
    expect(prompt).toMatch(/6/);
  });

  it.each([1, 8, 3.5, "5", null])("days=%j fuera de rango responde 400", async (d) => {
    const { status } = await post(planWith(3), { destination: "Antigua", days: d });
    expect(status).toBe(400);
  });

  it("el total del plan es la suma de los días aunque el modelo se equivoque", async () => {
    const { status, json } = await post(planWith(3, { totalUsd: 1 }, 30));
    expect(status).toBe(200);
    expect(json.plan.totalUsd).toBe(90);
    expect(json.plan.days.every((d: { costUsd: number }) => d.costUsd === 30)).toBe(true);
  });

  it.each([-1, 10.5, "20"])("costo de día %j responde 502 invalid_plan", async (c) => {
    const { status, json } = await post(planWith(3, {}, c));
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });

  it("un día sin costo responde 502 invalid_plan", async () => {
    const p = planWith(3);
    delete (p.days[1] as Record<string, unknown>).costUsd;
    const { status, json } = await post(p);
    expect(status).toBe(502);
    expect(json).toEqual({ error: "invalid_plan" });
  });
});
EOF
cat > ui.juez.test.ts <<'EOF'
/** Juez de la tarea `ui`: función pública requestPlan en src/lib/plan-client.ts, con fetch simulado. Sin red. */
import { describe, it, expect, vi, afterEach } from "vitest";

afterEach(() => vi.unstubAllGlobals());

const plan = { intro: "i", days: [], hiddenGem: {}, localFood: {}, totalUsd: 10 };

function stubFetch(response: { ok: boolean; status: number; body: unknown }) {
  const fn = vi.fn(async () => ({
    ok: response.ok,
    status: response.status,
    json: async () => response.body,
  }));
  vi.stubGlobal("fetch", fn);
  return fn;
}

describe("Juez · cliente del plan en la interfaz", () => {
  it("envía destino, contexto y días a /api/ai-plan", async () => {
    const fetchFn = stubFetch({ ok: true, status: 200, body: { plan } });
    const { requestPlan } = await import("@/lib/plan-client");
    await requestPlan({ destination: "Antigua", context: "Guatemala", days: 5 });
    const [url, init] = fetchFn.mock.calls[0] as unknown as [string, { method: string; body: string }];
    expect(url).toBe("/api/ai-plan");
    expect(init.method).toBe("POST");
    expect(JSON.parse(init.body)).toEqual({ destination: "Antigua", context: "Guatemala", days: 5 });
  });

  it("devuelve el plan cuando llega con 200", async () => {
    stubFetch({ ok: true, status: 200, body: { plan } });
    const { requestPlan } = await import("@/lib/plan-client");
    expect(await requestPlan({ destination: "Antigua", days: 3 })).toEqual(plan);
  });

  it("devuelve null si el API responde 502 (plan que no se muestra)", async () => {
    stubFetch({ ok: false, status: 502, body: { error: "invalid_plan" } });
    const { requestPlan } = await import("@/lib/plan-client");
    expect(await requestPlan({ destination: "Antigua", days: 3 })).toBeNull();
  });

  it("devuelve null si fetch lanza, sin propagar la excepción", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => { throw new Error("red"); }));
    vi.spyOn(console, "error").mockImplementation(() => {});
    const { requestPlan } = await import("@/lib/plan-client");
    expect(await requestPlan({ destination: "Antigua", days: 3 })).toBeNull();
  });

  it("si no se pide días, manda 3", async () => {
    const fetchFn = stubFetch({ ok: true, status: 200, body: { plan } });
    const { requestPlan } = await import("@/lib/plan-client");
    await requestPlan({ destination: "Antigua" });
    const [, init] = fetchFn.mock.calls[0] as unknown as [string, { body: string }];
    expect(JSON.parse(init.body).days).toBe(3);
  });
});
EOF
